32	// recordFirstStreamError sends err to errChan if the channel is empty; subsequent errors are discarded.
33	func recordFirstStreamError(errChan chan error, err error) {
34		if err == nil {
35			return
36		}
37	
38		select {
39		case errChan <- err:
40		default:
41			// Second+ error discarded; log for observability
42			debuglog.Debug(debuglog.Wire, "additional stream error discarded: %v\n", err)
43		}
44	}
45	
46	// joinPromptSections trims each part, drops empty ones, and joins the rest with newline separators.
47	func joinPromptSections(parts ...string) string {
48		sections := make([]string, 0, len(parts))
49		for _, part := range parts {
50			trimmed := strings.TrimSpace(part)
51			if trimmed != "" {
52				sections = append(sections, trimmed)
53			}
54		}
55	
56		return strings.Join(sections, "\n")
57	}
58	
59	// Send processes a chat request and applies file changes for create_coding_feature pattern
60	func (o *Chatter) Send(ctx context.Context, request *domain.ChatRequest, opts *domain.ChatOptions) (session *fsdb.Session, err error) {
61		// Use o.model (normalized) for NeedsRawMode check instead of opts.Model
62		// This ensures case-insensitive model names work correctly (e.g., "GPT-5" → "gpt-5")
63		if o.vendor.NeedsRawMode(o.model) {
64			opts.Raw = true
65		}
66		if session, err = o.BuildSession(request, opts.Raw); err != nil {
67			return
68		}
69	
70		vendorMessages := session.GetVendorMessages()
71	
72		if debuglog.GetLevel() >= debuglog.Wire {
73			debuglog.Debug(debuglog.Wire, "FABRIC->LLM request messages (%d)\n", len(vendorMessages))
74			for i, msg := range vendorMessages {
75				debuglog.Debug(debuglog.Wire, "FABRIC->LLM [%d] role=%s content=%q\n", i, msg.Role, msg.Content)
76				if len(msg.MultiContent) > 0 {
77					debuglog.Debug(debuglog.Wire, "FABRIC->LLM [%d] parts=%d\n", i, len(msg.MultiContent))
78				}
79			}
80		}
81		if len(vendorMessages) == 0 {
82			if session.Name != "" {
83				err = o.db.Sessions.SaveSession(session)
84				if err != nil {
85					return
86				}
87			}
88			err = errors.New(i18n.T("chatter_error_no_messages_provided"))
89			return
90		}
91	
92		// Always use the normalized model name from the Chatter
93		// This handles cases where user provides "GPT-5" but we've normalized it to "gpt-5"
94		opts.Model = o.model
95	
96		if opts.ModelContextLength == 0 {
97			opts.ModelContextLength = o.modelContextLength
98		}
99	
100		message := ""
101	
102		if o.Stream {
103			responseChan := make(chan domain.StreamUpdate)
104			errChan := make(chan error, 1)
105			done := make(chan struct{})
106			printedStream := false
107	
108			go func() {
109				defer close(done)
110				if streamErr := o.vendor.SendStream(ctx, session.GetVendorMessages(), opts, responseChan); streamErr != nil {
111					recordFirstStreamError(errChan, streamErr)
112				}
113			}()
114	
115			for update := range responseChan {
116				if debuglog.GetLevel() >= debuglog.Wire {
117					debuglog.Debug(debuglog.Wire, "LLM->FABRIC stream update type=%s content=%q\n", update.Type, update.Content)
118					if update.Usage != nil {
119						debuglog.Debug(debuglog.Wire, "LLM->FABRIC stream usage input=%d output=%d total=%d\n", update.Usage.InputTokens, update.Usage.OutputTokens, update.Usage.TotalTokens)
120					}
121				}
122				if opts.UpdateChan != nil {
123					opts.UpdateChan <- update
124				}
125				switch update.Type {
126				case domain.StreamTypeContent:
127					message += update.Content
128					if !opts.SuppressThink && !opts.Quiet {
129						fmt.Print(update.Content)
130						printedStream = true
131					}
132				case domain.StreamTypeUsage:
133					if opts.ShowMetadata && update.Usage != nil && !opts.Quiet {
134						fmt.Fprintf(
135							os.Stderr,
136							"\n%s\n",
137							fmt.Sprintf(
138								i18n.T("chatter_log_stream_usage_metadata"),
139								update.Usage.InputTokens,
140								update.Usage.OutputTokens,
141								update.Usage.TotalTokens,
142							),
143						)
144					}
145				case domain.StreamTypeError:
146					if !opts.Quiet {
147						fmt.Fprintf(os.Stderr, "%s\n", fmt.Sprintf(i18n.T("chatter_error_stream_update"), update.Content))
148					}
149					recordFirstStreamError(errChan, errors.New(update.Content))
150				}
151			}
152	
153			if printedStream && !opts.SuppressThink && !strings.HasSuffix(message, "\n") && !opts.Quiet {
154				fmt.Println()
155			}
156	
157			// Wait for goroutine to finish
158			<-done
159	
160			// Check for errors in errChan
161			select {
162			case streamErr := <-errChan:
163				if streamErr != nil {
164					err = streamErr
165					return
166				}
167			default:
168				// No errors, continue
169			}
170		} else {
171			if message, err = o.vendor.Send(ctx, session.GetVendorMessages(), opts); err != nil {
172				return
173			}
174			if debuglog.GetLevel() >= debuglog.Wire {
175				debuglog.Debug(debuglog.Wire, "LLM->FABRIC response content=%q\n", message)
176			}
177		}
178	
179		if opts.SuppressThink && !o.DryRun {
180			message = domain.StripThinkBlocks(message, opts.ThinkStartTag, opts.ThinkEndTag)
181		}
182	
183		if message == "" {
184			session = nil
185			err = errors.New(i18n.T("chatter_error_empty_response"))
186			return
187		}
188	
189		// Process file changes for create_coding_feature pattern
190		if request.PatternName == "create_coding_feature" {
191			summary, fileChanges, parseErr := domain.ParseFileChanges(message)
192			if parseErr != nil {
193				fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_parse_file_changes_failed"), parseErr))
194			} else if len(fileChanges) > 0 {
195				projectRoot, err := os.Getwd()
196				if err != nil {
197					fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_get_current_directory_failed"), err))
198				} else {
199					if applyErr := domain.ApplyFileChanges(projectRoot, fileChanges); applyErr != nil {
200						fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_apply_file_changes_failed"), applyErr))
201					} else {
202						fmt.Println(i18n.T("chatter_info_file_changes_applied_successfully"))
203						fmt.Printf("%s\n\n", i18n.T("chatter_help_review_changes_with_git_diff"))
204					}
205				}
206			}
207			message = summary
208		}
209	
210		session.Append(&chat.ChatCompletionMessage{Role: chat.ChatMessageRoleAssistant, Content: message})
211	
212		if session.Name != "" {
213			err = o.db.Sessions.SaveSession(session)
214		}
215		return
216	}
217	
218	func (o *Chatter) BuildSession(request *domain.ChatRequest, raw bool) (session *fsdb.Session, err error) {
219		if request.SessionName != "" {
220			var sess *fsdb.Session
221			if sess, err = o.db.Sessions.Get(request.SessionName); err != nil {
222				err = fmt.Errorf(i18n.T("chatter_error_find_session"), request.SessionName, err)
223				return
224			}
225			session = sess
226		} else {
227			session = &fsdb.Session{}
228		}
229	
230		if request.Meta != "" {
231			session.Append(&chat.ChatCompletionMessage{Role: domain.ChatMessageRoleMeta, Content: request.Meta})
232		}
233	
234		// if a context name is provided, retrieve it from the database
235		var contextContent string
236		if request.ContextName != "" {
237			var ctx *fsdb.Context
238			if ctx, err = o.db.Contexts.Get(request.ContextName); err != nil {
239				err = fmt.Errorf(i18n.T("chatter_error_find_context"), request.ContextName, err)
240				return
241			}
242			contextContent = ctx.Content
243		}
244	
245		// Process template variables in message content
246		// Double curly braces {{variable}} indicate template substitution
247		// Ensure we have a message before processing
248		if request.Message == nil {
249			request.Message = &chat.ChatCompletionMessage{
250				Role:    chat.ChatMessageRoleUser,
251				Content: "",
252			}
253		}
254	
255		// Now we know request.Message is not nil, process template variables
256		if request.InputHasVars && !request.NoVariableReplacement {
257			request.Message.Content, err = template.ApplyTemplate(request.Message.Content, request.PatternVariables, "")
258			if err != nil {
259				return nil, err
260			}
261		}
262	
263		var patternContent string
264		inputUsed := false
265		if request.PatternName != "" {
266			var pattern *fsdb.Pattern
267			if request.NoVariableReplacement {
268				pattern, err = o.db.Patterns.GetWithoutVariables(request.PatternName, request.Message.Content)
269			} else {
270				pattern, err = o.db.Patterns.GetApplyVariables(request.PatternName, request.PatternVariables, request.Message.Content)
271			}
272	
273			if err != nil {
274				return nil, fmt.Errorf(i18n.T("chatter_error_get_pattern"), request.PatternName, err)
275			}
276			patternContent = pattern.Pattern
277			inputUsed = true
278		}
279	
280		systemMessage := joinPromptSections(contextContent, patternContent)
281	
282		if request.StrategyName != "" {
283			strategy, err := strategy.LoadStrategy(request.StrategyName)
284			if err != nil {
285				return nil, fmt.Errorf(i18n.T("chatter_error_load_strategy"), request.StrategyName, err)
286			}
287			if strategy != nil && strategy.Prompt != "" {
288				systemMessage = joinPromptSections(strategy.Prompt, systemMessage)
289			}
290		}
291	
292		// Apply refined language instruction if specified
293		if request.Language != "" && request.Language != "en" {
294			// Refined instruction: Execute pattern using user input, then translate the entire response.
295			systemMessage = fmt.Sprintf(i18n.T("chatter_prompt_enforce_response_language"), systemMessage, request.Language)
296		}
297	
298		if raw {
299			var finalContent string
300			if systemMessage != "" {
301				if request.PatternName != "" {
302					finalContent = systemMessage
303				} else {
304					finalContent = fmt.Sprintf("%s\n\n%s", systemMessage, request.Message.Content)
305				}
306	
307				// Handle MultiContent properly in raw mode
308				if len(request.Message.MultiContent) > 0 {
309					// When we have attachments, add the text as a text part in MultiContent
310					newMultiContent := []chat.ChatMessagePart{
311						{
312							Type: chat.ChatMessagePartTypeText,
313							Text: finalContent,
314						},
315					}
316					// Add existing non-text parts (like images)
317					for _, part := range request.Message.MultiContent {
318						if part.Type != chat.ChatMessagePartTypeText {
319							newMultiContent = append(newMultiContent, part)
320						}
321					}
322					request.Message = &chat.ChatCompletionMessage{
323						Role:         chat.ChatMessageRoleUser,
324						MultiContent: newMultiContent,
325					}
326				} else {
327					// No attachments, use regular Content field
328					request.Message = &chat.ChatCompletionMessage{
329						Role:    chat.ChatMessageRoleUser,
330						Content: finalContent,
331					}
332				}
333			}
334			if request.Message != nil {
335				session.Append(request.Message)
336			}
337		} else {
338			if systemMessage != "" {
339				session.Append(&chat.ChatCompletionMessage{Role: chat.ChatMessageRoleSystem, Content: systemMessage})
340			}
341			// If multi-part content, it is in the user message, and should be added.
342			// Otherwise, we should only add it if we have not already used it in the systemMessage.
343			if len(request.Message.MultiContent) > 0 || (request.Message != nil && !inputUsed) {
344				session.Append(request.Message)
345			}
346		}
347	
348		if session.IsEmpty() {
349			session = nil
350			err = errors.New(i18n.T("chatter_error_no_session_pattern_user_messages"))
351		}
352		return
353	}
