32	// recordFirstStreamError sends err to errChan if the channel is empty; subsequent errors are discarded.
33	func recordFirstStreamError(errChan chan error, err error) {
34		if err == nil {
35			return
36		}
37	
38		select {
39		case errChan <- err:
40		default:
41			// Second+ error discarded; log for observability
42			debuglog.Debug(debuglog.Wire, "additional stream error discarded: %v\n", err)
43		}
44	}
