46	// joinPromptSections trims each part, drops empty ones, and joins the rest with newline separators.
47	func joinPromptSections(parts ...string) string {
48		sections := make([]string, 0, len(parts))
49		for _, part := range parts {
50			trimmed := strings.TrimSpace(part)
51			if trimmed != "" {
52				sections = append(sections, trimmed)
53			}
54		}
55	
56		return strings.Join(sections, "\n")
57	}
