113			}()
114	
115			for update := range responseChan {
116				if debuglog.GetLevel() >= debuglog.Wire {
117					debuglog.Debug(debuglog.Wire, "LLM->FABRIC stream update type=%s content=%q\n", update.Type, update.Content)
118					if update.Usage != nil {
119						debuglog.Debug(debuglog.Wire, "LLM->FABRIC stream usage input=%d output=%d total=%d\n", update.Usage.InputTokens, update.Usage.OutputTokens, update.Usage.TotalTokens)
120					}
121				}
122				if opts.UpdateChan != nil {
123					opts.UpdateChan <- update
124				}
125				switch update.Type {
126				case domain.StreamTypeContent:
127					message += update.Content
128					if !opts.SuppressThink && !opts.Quiet {
129						fmt.Print(update.Content)
130						printedStream = true
131					}
132				case domain.StreamTypeUsage:
133					if opts.ShowMetadata && update.Usage != nil && !opts.Quiet {
134						fmt.Fprintf(
135							os.Stderr,
136							"\n%s\n",
137							fmt.Sprintf(
138								i18n.T("chatter_log_stream_usage_metadata"),
139								update.Usage.InputTokens,
140								update.Usage.OutputTokens,
141								update.Usage.TotalTokens,
142							),
143						)
144					}
145				case domain.StreamTypeError:
146					if !opts.Quiet {
147						fmt.Fprintf(os.Stderr, "%s\n", fmt.Sprintf(i18n.T("chatter_error_stream_update"), update.Content))
148					}
149					recordFirstStreamError(errChan, errors.New(update.Content))
150				}
151			}
152	
153			if printedStream && !opts.SuppressThink && !strings.HasSuffix(message, "\n") && !opts.Quiet {
154				fmt.Println()
155			}
156	
157			// Wait for goroutine to finish
158			<-done
159	
160			// Check for errors in errChan
161			select {
162			case streamErr := <-errChan:
163				if streamErr != nil {
164					err = streamErr
165					return
166				}
167			default:
168				// No errors, continue
169			}
170		} else {
171			if message, err = o.vendor.Send(ctx, session.GetVendorMessages(), opts); err != nil {
172				return
173			}
174			if debuglog.GetLevel() >= debuglog.Wire {
175				debuglog.Debug(debuglog.Wire, "LLM->FABRIC response content=%q\n", message)
176			}
177		}
178	
179		if opts.SuppressThink && !o.DryRun {
180			message = domain.StripThinkBlocks(message, opts.ThinkStartTag, opts.ThinkEndTag)
181		}
182	
183		if message == "" {
184			session = nil
185			err = errors.New(i18n.T("chatter_error_empty_response"))
186			return
187		}
188	
189		// Process file changes for create_coding_feature pattern
190		if request.PatternName == "create_coding_feature" {
191			summary, fileChanges, parseErr := domain.ParseFileChanges(message)
192			if parseErr != nil {
193				fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_parse_file_changes_failed"), parseErr))
194			} else if len(fileChanges) > 0 {
195				projectRoot, err := os.Getwd()
196				if err != nil {
197					fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_get_current_directory_failed"), err))
198				} else {
199					if applyErr := domain.ApplyFileChanges(projectRoot, fileChanges); applyErr != nil {
200						fmt.Printf("%s\n", fmt.Sprintf(i18n.T("chatter_warning_apply_file_changes_failed"), applyErr))
201					} else {
202						fmt.Println(i18n.T("chatter_info_file_changes_applied_successfully"))
203						fmt.Printf("%s\n\n", i18n.T("chatter_help_review_changes_with_git_diff"))
204					}
205				}
206			}
207			message = summary
208		}
209	
210		session.Append(&chat.ChatCompletionMessage{Role: chat.ChatMessageRoleAssistant, Content: message})
211	
212		if session.Name != "" {
213			err = o.db.Sessions.SaveSession(session)
214		}
215		return
216	}
