218	func (o *Chatter) BuildSession(request *domain.ChatRequest, raw bool) (session *fsdb.Session, err error) {
219		if request.SessionName != "" {
220			var sess *fsdb.Session
221			if sess, err = o.db.Sessions.Get(request.SessionName); err != nil {
222				err = fmt.Errorf(i18n.T("chatter_error_find_session"), request.SessionName, err)
223				return
224			}
225			session = sess
226		} else {
227			session = &fsdb.Session{}
228		}
229	
230		if request.Meta != "" {
231			session.Append(&chat.ChatCompletionMessage{Role: domain.ChatMessageRoleMeta, Content: request.Meta})
232		}
233	
234		// if a context name is provided, retrieve it from the database
235		var contextContent string
236		if request.ContextName != "" {
237			var ctx *fsdb.Context
238			if ctx, err = o.db.Contexts.Get(request.ContextName); err != nil {
239				err = fmt.Errorf(i18n.T("chatter_error_find_context"), request.ContextName, err)
240				return
241			}
242			contextContent = ctx.Content
243		}
244	
245		// Process template variables in message content
246		// Double curly braces {{variable}} indicate template substitution
247		// Ensure we have a message before processing
248		if request.Message == nil {
249			request.Message = &chat.ChatCompletionMessage{
250				Role:    chat.ChatMessageRoleUser,
251				Content: "",
252			}
253		}
254	
255		// Now we know request.Message is not nil, process template variables
256		if request.InputHasVars && !request.NoVariableReplacement {
257			request.Message.Content, err = template.ApplyTemplate(request.Message.Content, request.PatternVariables, "")
258			if err != nil {
259				return nil, err
260			}
261		}
262	
263		var patternContent string
264		inputUsed := false
265		if request.PatternName != "" {
266			var pattern *fsdb.Pattern
267			if request.NoVariableReplacement {
268				pattern, err = o.db.Patterns.GetWithoutVariables(request.PatternName, request.Message.Content)
269			} else {
270				pattern, err = o.db.Patterns.GetApplyVariables(request.PatternName, request.PatternVariables, request.Message.Content)
271			}
272	
273			if err != nil {
274				return nil, fmt.Errorf(i18n.T("chatter_error_get_pattern"), request.PatternName, err)
275			}
276			patternContent = pattern.Pattern
277			inputUsed = true
278		}
279	
280		systemMessage := joinPromptSections(contextContent, patternContent)
281	
282		if request.StrategyName != "" {
283			strategy, err := strategy.LoadStrategy(request.StrategyName)
284			if err != nil {
285				return nil, fmt.Errorf(i18n.T("chatter_error_load_strategy"), request.StrategyName, err)
286			}
287			if strategy != nil && strategy.Prompt != "" {
288				systemMessage = joinPromptSections(strategy.Prompt, systemMessage)
289			}
290		}
291	
292		// Apply refined language instruction if specified
293		if request.Language != "" && request.Language != "en" {
294			// Refined instruction: Execute pattern using user input, then translate the entire response.
295			systemMessage = fmt.Sprintf(i18n.T("chatter_prompt_enforce_response_language"), systemMessage, request.Language)
296		}
297	
298		if raw {
299			var finalContent string
300			if systemMessage != "" {
301				if request.PatternName != "" {
302					finalContent = systemMessage
303				} else {
304					finalContent = fmt.Sprintf("%s\n\n%s", systemMessage, request.Message.Content)
305				}
306	
307				// Handle MultiContent properly in raw mode
308				if len(request.Message.MultiContent) > 0 {
309					// When we have attachments, add the text as a text part in MultiContent
310					newMultiContent := []chat.ChatMessagePart{
311						{
312							Type: chat.ChatMessagePartTypeText,
313							Text: finalContent,
314						},
315					}
316					// Add existing non-text parts (like images)
317					for _, part := range request.Message.MultiContent {
318						if part.Type != chat.ChatMessagePartTypeText {
319							newMultiContent = append(newMultiContent, part)
320						}
321					}
322					request.Message = &chat.ChatCompletionMessage{
323						Role:         chat.ChatMessageRoleUser,
324						MultiContent: newMultiContent,
325					}
326				} else {
327					// No attachments, use regular Content field
328					request.Message = &chat.ChatCompletionMessage{
329						Role:    chat.ChatMessageRoleUser,
330						Content: finalContent,
331					}
332				}
333			}
334			if request.Message != nil {
335				session.Append(request.Message)
336			}
337		} else {
338			if systemMessage != "" {
339				session.Append(&chat.ChatCompletionMessage{Role: chat.ChatMessageRoleSystem, Content: systemMessage})
340			}
341			// If multi-part content, it is in the user message, and should be added.
342			// Otherwise, we should only add it if we have not already used it in the systemMessage.
343			if len(request.Message.MultiContent) > 0 || (request.Message != nil && !inputUsed) {
344				session.Append(request.Message)
345			}
346		}
347	
348		if session.IsEmpty() {
349			session = nil
350			err = errors.New(i18n.T("chatter_error_no_session_pattern_user_messages"))
351		}
352		return
353	}
