26	)
27	
28	const (
29		vendorName            = "Codex"
30		defaultBaseURL        = "https://chatgpt.com/backend-api/codex"
31		defaultAuthBaseURL    = "https://auth.openai.com"
32		defaultClientVersion  = "1.0.0"
33		defaultOriginator     = "codex_cli_rs"
34		defaultUserAgent      = "codex_cli_rs/fabric"
35		defaultCallbackPort   = 1455
36		oauthClientID         = "app_EMoamEEZ73f0CkXaXp7hrann"
37		oauthCallbackPath     = "/auth/callback"
38		oauthStateBytes       = 32
39		oauthVerifierBytes    = 32
40		oauthTimeout          = 5 * time.Minute
41		tokenRefreshLeeway    = 5 * time.Minute
42		modelsRequestTimeout  = 30 * time.Second
43		defaultRoundTripLimit = 4096
44	)
45	
46	const oauthScope = "openid profile email offline_access api.connectors.read api.connectors.invoke"
47	
48	// Client implements the Codex-backed AI vendor.
49	type Client struct {
50		*openaivendor.Client
51	
52		AccessToken  *plugins.Setting
53		RefreshToken *plugins.Setting
54		AccountID    *plugins.Setting
55		AuthBaseURL  *plugins.SetupQuestion
56	
57		authHTTPClient *http.Client
58		apiHTTPClient  *http.Client
59	
60		tokenMu sync.Mutex
61	}
62	
63	type modelInfo struct {
64		Slug           string `json:"slug"`
65		SupportedInAPI bool   `json:"supported_in_api"`
66		Visibility     string `json:"visibility"`
67	}
68	
69	type modelsResponse struct {
70		Models []modelInfo `json:"models"`
71	}
72	
73	// NewClient creates a new Codex vendor client.
74	func NewClient() *Client {
75		client := &Client{}
76		client.Client = openaivendor.NewClientCompatibleNoSetupQuestions(vendorName, client.configure)
77		client.ImplementsResponses = true
78	
79		client.AccessToken = client.AddSetting("Access Token", false)
80		client.RefreshToken = client.AddSetting("Refresh Token", true)
81		client.AccountID = client.AddSetting("Account ID", true)
82	
83		client.ApiBaseURL = client.AddSetupQuestionWithEnvName("Base URL", false,
84			"Enter your Codex API base URL")
85		client.ApiBaseURL.Value = defaultBaseURL
86	
87		client.AuthBaseURL = client.AddSetupQuestionWithEnvName("Auth Base URL", false,
88			"Enter your Codex OAuth base URL")
89		client.AuthBaseURL.Value = defaultAuthBaseURL
90	
91		client.authHTTPClient = &http.Client{Timeout: modelsRequestTimeout}
92		return client
93	}
94	
95	// Setup runs interactive Codex configuration, including browser-based OAuth.
96	func (c *Client) Setup() error {
97		if err := c.ApiBaseURL.Ask(vendorName); err != nil {
98			return err
99		}
100		if err := c.AuthBaseURL.Ask(vendorName); err != nil {
101			return err
102		}
103	
104		ctx, cancel := context.WithTimeout(context.Background(), oauthTimeout)
105		defer cancel()
106	
107		fmt.Println()
108		fmt.Println(i18n.T("codex_starting_browser_login"))
109		debuglog.Debug(debuglog.Detailed, "Codex setup: starting OAuth flow against %s\n", c.AuthBaseURL.Value)
110	
111		tokens, err := c.runOAuthFlow(ctx, openBrowser)
112		if err != nil {
113			return err
114		}
115	
116		accountID, err := c.extractAccountID(tokens.IDToken, tokens.AccessToken)
117		if err != nil {
118			return err
119		}
120	
121		c.setSettingValue(c.AccessToken, tokens.AccessToken)
122		c.setSettingValue(c.RefreshToken, tokens.RefreshToken)
123		c.setSettingValue(c.AccountID, accountID)
124	
125		return c.configure()
126	}
127	
128	func (c *Client) configure() error {
129		c.authHTTPClient = &http.Client{Timeout: modelsRequestTimeout}
130	
131		if strings.TrimSpace(c.ApiBaseURL.Value) == "" {
132			c.ApiBaseURL.Value = defaultBaseURL
133		}
134		if strings.TrimSpace(c.AuthBaseURL.Value) == "" {
135			c.AuthBaseURL.Value = defaultAuthBaseURL
136		}
137		if strings.TrimSpace(c.RefreshToken.Value) == "" {
138			return errors.New(i18n.T("codex_refresh_token_required"))
139		}
140	
141		if _, _, err := c.ensureAccessToken(context.Background(), false); err != nil {
142			return err
143		}
144	
145		transport := &authTransport{
146			client:  c,
147			wrapped: http.DefaultTransport,
148		}
149		c.apiHTTPClient = &http.Client{Transport: transport}
150	
151		apiClient := openaiapi.NewClient(
152			option.WithBaseURL(strings.TrimRight(c.ApiBaseURL.Value, "/")),
153			option.WithHTTPClient(c.apiHTTPClient),
154		)
155		c.ApiClient = &apiClient
156		debuglog.Debug(debuglog.Detailed, "Codex configure: authenticated account=%s base_url=%s\n", c.AccountID.Value, c.ApiBaseURL.Value)
157	
158		return nil
159	}
160	
161	// ListModels returns the Codex models available to the configured account.
162	func (c *Client) ListModels(ctx context.Context) ([]string, error) {
163		if c.apiHTTPClient == nil {
164			if err := c.configure(); err != nil {
165				return nil, err
166			}
167		}
168	
169		ctx, cancel := context.WithTimeout(ctx, modelsRequestTimeout)
170		defer cancel()
171	
172		modelsURL := strings.TrimRight(c.ApiBaseURL.Value, "/") + "/models"
173		req, err := http.NewRequestWithContext(ctx, http.MethodGet, modelsURL, nil)
174		if err != nil {
175			return nil, err
176		}
177		query := req.URL.Query()
178		query.Set("client_version", codexClientVersion())
179		req.URL.RawQuery = query.Encode()
180		debuglog.Debug(debuglog.Trace, "Codex ListModels request: %s\n", req.URL.String())
181	
182		resp, err := c.apiHTTPClient.Do(req)
183		if err != nil {
184			return nil, c.mapRequestError(err)
185		}
186		defer resp.Body.Close()
187	
188		body, err := io.ReadAll(resp.Body)
189		if err != nil {
190			return nil, err
191		}
192		if resp.StatusCode != http.StatusOK {
193			return nil, c.errorFromHTTPResponse(resp.StatusCode, body)
194		}
195	
196		var decoded modelsResponse
197		if err := json.Unmarshal(body, &decoded); err != nil {
198			return nil, fmt.Errorf(i18n.T("codex_decode_models_response_failed"), err)
199		}
200	
201		models := make([]string, 0, len(decoded.Models))
202		for _, model := range decoded.Models {
203			if model.Slug == "" || !model.SupportedInAPI || model.Visibility != "list" {
204				continue
205			}
206			models = append(models, model.Slug)
207		}
208	
209		return models, nil
210	}
211	
212	// Send sends a request to Codex and returns the final text output.
213	func (c *Client) Send(ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions) (string, error) {
214		if opts.ImageFile != "" {
215			return "", errors.New(i18n.T("codex_image_file_not_supported"))
216		}
217		if c.ApiClient == nil {
218			if err := c.configure(); err != nil {
219				return "", err
220			}
221		}
222	
223		req := c.buildCodexResponseParams(msgs, opts)
224		stream := c.ApiClient.Responses.NewStreaming(ctx, req)
225		defer stream.Close()
226	
227		var (
228			builder       strings.Builder
229			completedResp *responses.Response
230		)
231		for stream.Next() {
232			event := stream.Current()
233			switch event.Type {
234			case string(constant.ResponseOutputTextDelta("").Default()):
235				builder.WriteString(event.AsResponseOutputTextDelta().Delta)
236			case "response.completed":
237				resp := event.AsResponseCompleted().Response
238				completedResp = &resp
239			}
240		}
241	
242		if err := c.mapRequestError(stream.Err()); err != nil {
243			return "", err
244		}
