252	// SendStream sends a request to Codex and streams the response text updates.
253	func (c *Client) SendStream(
254		ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions, channel chan domain.StreamUpdate,
255	) error {
256		defer close(channel)
257	
258		if opts.ImageFile != "" {
259			return errors.New(i18n.T("codex_image_file_not_supported"))
260		}
261		if c.ApiClient == nil {
262			if err := c.configure(); err != nil {
263				return err
264			}
265		}
266	
267		req := c.buildCodexResponseParams(msgs, opts)
268		stream := c.ApiClient.Responses.NewStreaming(ctx, req)
269		defer stream.Close()
270		for stream.Next() {
271			event := stream.Current()
272			switch event.Type {
273			case string(constant.ResponseOutputTextDelta("").Default()):
274				if err := sendStreamUpdate(ctx, channel, domain.StreamUpdate{
275					Type:    domain.StreamTypeContent,
276					Content: event.AsResponseOutputTextDelta().Delta,
277				}); err != nil {
278					return err
279				}
280			case string(constant.ResponseOutputTextDone("").Default()):
281				continue
282			}
283		}
284	
285		if stream.Err() == nil {
286			if err := sendStreamUpdate(ctx, channel, domain.StreamUpdate{
287				Type:    domain.StreamTypeContent,
288				Content: "\n",
289			}); err != nil {
290				return err
291			}
292		}
293	
294		return c.mapRequestError(stream.Err())
295	}
296	
297	func sendStreamUpdate(ctx context.Context, channel chan domain.StreamUpdate, update domain.StreamUpdate) error {
298		select {
299		case <-ctx.Done():
300			return ctx.Err()
301		case channel <- update:
302			return nil
303		}
304	}
