306	func (c *Client) buildCodexResponseParams(
307		msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions,
308	) responses.ResponseNewParams {
309		instructions, filteredMsgs := codexInstructionsAndMessages(msgs)
310		req := c.BuildResponseParams(filteredMsgs, opts)
311		req.Instructions = openaiapi.String(instructions)
312		req.Store = openaiapi.Bool(false)
313		return req
314	}
315	
316	func codexInstructionsAndMessages(
317		msgs []*chat.ChatCompletionMessage,
318	) (string, []*chat.ChatCompletionMessage) {
319		filtered := make([]*chat.ChatCompletionMessage, 0, len(msgs))
320		instructions := make([]string, 0, len(msgs))
321	
322		for _, msg := range msgs {
323			if msg == nil {
324				continue
325			}
326			switch msg.Role {
327			case chat.ChatMessageRoleSystem, chat.ChatMessageRoleDeveloper:
328				if text := codexMessageText(*msg); text != "" {
329					instructions = append(instructions, text)
330				}
331			default:
332				filtered = append(filtered, msg)
333			}
334		}
335	
336		if len(instructions) == 0 {
337			return "You are a helpful assistant.", filtered
338		}
339	
340		return strings.Join(instructions, "\n\n"), filtered
341	}
342	
343	func codexMessageText(msg chat.ChatCompletionMessage) string {
344		if text := strings.TrimSpace(msg.Content); text != "" {
345			return text
346		}
347	
348		if len(msg.MultiContent) == 0 {
349			return ""
350		}
351	
352		parts := make([]string, 0, len(msg.MultiContent))
353		for _, part := range msg.MultiContent {
354			if part.Type == chat.ChatMessagePartTypeText {
355				if text := strings.TrimSpace(part.Text); text != "" {
356					parts = append(parts, text)
357				}
358			}
359		}
360	
361		return strings.Join(parts, "\n")
362	}
