83	
84		openBrowserFn := func(authURL string) error {
85			parsed, err := url.Parse(authURL)
86			if err != nil {
87				return err
88			}
89			callbackURL := parsed.Query().Get("redirect_uri")
90			callbackParsed, err := url.Parse(callbackURL)
