106			}
107			state := parsed.Query().Get("state")
108	
109			go func() {
110				_, _ = http.Get(callbackURL + "?code=auth-code&state=" + url.QueryEscape(state))
111			}()
112	
113			return nil
114		}
115	
116		ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
