		}
		fmt.Fprintf(w, "data: %s\n\n", marshalJSON(t, map[string]any{
			"type": "response.completed",
			"response": map[string]any{
				"output": []any{
					map[string]any{
						"type": "message",
						"content": []any{
							map[string]any{
								"type": "output_text",
								"text": "hello from codex",
								"annotations": []any{
