498			t.Fatalf("streamed content = %q, want %q", builder.String(), "hello world\n")
499		}
500	}
501	
502	func TestSendStreamClosesChannelAndMapsHTTPError(t *testing.T) {
503		apiServer := httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
504			if r.URL.Path != "/responses" {
505				http.NotFound(w, r)
506				return
507			}
508			http.Error(w, `{"error":{"message":"usage limit reached"}}`, http.StatusTooManyRequests)
509		}))
510		defer apiServer.Close()
511	
512		client := newConfiguredTestClient(t, apiServer.URL, "acct_stream_error", testJWT("acct_stream_error", time.Now().Add(time.Hour)))
513	
514		updates := make(chan domain.StreamUpdate, 1)
515		err := client.SendStream(context.Background(), []*chat.ChatCompletionMessage{
516			{Role: chat.ChatMessageRoleUser, Content: "Hello"},
517		}, &domain.ChatOptions{
518			Model: "gpt-5.4",
519		}, updates)
520		if err == nil {
521			t.Fatal("SendStream() error = nil, want mapped HTTP error")
522		}
523		if got := err.Error(); got != "codex usage limit reached" {
524			t.Fatalf("SendStream() error = %q, want %q", got, "codex usage limit reached")
525		}
526	
527		update, ok := <-updates
528		if ok {
529			t.Fatalf("expected closed channel after stream error, got update %#v", update)
530		}
531	}
532	
533	func newConfiguredTestClient(t *testing.T, apiBaseURL string, accountID string, accessToken string) *Client {
534		t.Helper()
535	
536		client := NewClient()
537		client.ApiBaseURL.Value = apiBaseURL
538		client.AuthBaseURL.Value = defaultAuthBaseURL
539		client.RefreshToken.Value = "refresh-test"
540		client.AccessToken.Value = accessToken
541		client.AccountID.Value = accountID
542	
543		if err := client.configure(); err != nil {
544			t.Fatalf("configure() error = %v", err)
545		}
546	
547		return client
548	}
549	
550	func testJWT(accountID string, expiry time.Time) string {
551		header := base64.RawURLEncoding.EncodeToString([]byte(`{"alg":"none","typ":"JWT"}`))
552		payloadBytes, _ := json.Marshal(map[string]any{
553			"exp": expiry.Unix(),
554			"https://api.openai.com/auth": map[string]any{
555				"chatgpt_account_id": accountID,
556				"chatgpt_plan_type":  "plus",
557			},
558		})
559		payload := base64.RawURLEncoding.EncodeToString(payloadBytes)
560		signature := base64.RawURLEncoding.EncodeToString([]byte("sig"))
561		return header + "." + payload + "." + signature
562	}
563	
564	func marshalJSON(t *testing.T, value any) string {
565		t.Helper()
566		encoded, err := json.Marshal(value)
567		if err != nil {
568			t.Fatalf("json.Marshal() error = %v", err)
569		}
570		return string(encoded)
571	}
