126	func (o *Client) sendStreamResponses(
127		ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions, channel chan domain.StreamUpdate,
128	) (err error) {
129		defer close(channel)
130	
131		req := o.buildResponseParams(msgs, opts)
132		stream := o.ApiClient.Responses.NewStreaming(ctx, req)
133		for stream.Next() {
134			event := stream.Current()
135			switch event.Type {
136			case string(constant.ResponseOutputTextDelta("").Default()):
137				channel <- domain.StreamUpdate{
138					Type:    domain.StreamTypeContent,
139					Content: event.AsResponseOutputTextDelta().Delta,
140				}
141			case string(constant.ResponseOutputTextDone("").Default()):
142				// The Responses API sends the full text again in the
143				// final "done" event. Since we've already streamed all
144				// delta chunks above, sending it would duplicate the
145				// output. Ignore it here to prevent doubled results.
146				continue
147			}
148		}
149		if stream.Err() == nil {
150			channel <- domain.StreamUpdate{
151				Type:    domain.StreamTypeContent,
152				Content: "\n",
153			}
154		}
155		return stream.Err()
156	}
