158	func (o *Client) Send(ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions) (ret string, err error) {
159		// Use Responses API for OpenAI, Chat Completions API for other providers
160		if o.supportsResponsesAPI() {
161			return o.sendResponses(ctx, msgs, opts)
162		}
163		return o.sendChatCompletions(ctx, msgs, opts)
164	}
