166	func (o *Client) sendResponses(ctx context.Context, msgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions) (ret string, err error) {
167		// Warn if model doesn't support image generation when image file is specified
168		if opts.ImageFile != "" {
169			checkImageGenerationCompatibility(opts.Model)
170		}
171	
172		// Validate model supports image generation if image file is specified
173		if opts.ImageFile != "" && !supportsImageGeneration(opts.Model) {
174			return "", fmt.Errorf("%s", fmt.Sprintf(i18n.T("openai_model_no_image_generation"), opts.Model, strings.Join(ImageGenerationSupportedModels, ", ")))
175		}
176	
177		req := o.buildResponseParams(msgs, opts)
178	
179		var resp *responses.Response
180		if resp, err = o.ApiClient.Responses.New(ctx, req); err != nil {
181			return
182		}
183	
184		// Extract and save images if requested
185		if err = o.extractAndSaveImages(resp, opts); err != nil {
186			return
187		}
188	
189		ret = o.extractText(resp)
190		return
191	}
