198	func (o *Client) NeedsRawMode(modelName string) bool {
199		openaiModelsPrefixes := []string{
200			"glm",
201			"gpt-5",
202			"o1",
203			"o3",
204			"o4",
205		}
206		openAIModelsNeedingRaw := []string{
207			"gpt-4o-mini-search-preview",
208			"gpt-4o-mini-search-preview-2025-03-11",
209			"gpt-4o-search-preview",
210			"gpt-4o-search-preview-2025-03-11",
211		}
212		for _, prefix := range openaiModelsPrefixes {
213			if strings.HasPrefix(modelName, prefix) {
214				return true
215			}
216		}
217		return slices.Contains(openAIModelsNeedingRaw, modelName)
218	}
219	
220	func parseReasoningEffort(level domain.ThinkingLevel) (shared.ReasoningEffort, bool) {
221		switch domain.ThinkingLevel(strings.ToLower(string(level))) {
222		case domain.ThinkingLow:
223			return shared.ReasoningEffortLow, true
224		case domain.ThinkingMedium:
225			return shared.ReasoningEffortMedium, true
226		case domain.ThinkingHigh:
227			return shared.ReasoningEffortHigh, true
228		default:
229			return "", false
230		}
231	}
232	
233	func (o *Client) buildResponseParams(
234		inputMsgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions,
235	) (ret responses.ResponseNewParams) {
236	
237		items := make([]responses.ResponseInputItemUnionParam, len(inputMsgs))
238		for i, msgPtr := range inputMsgs {
239			msg := *msgPtr
240			if strings.Contains(opts.Model, "deepseek") && len(inputMsgs) == 1 && msg.Role == chat.ChatMessageRoleSystem {
241				msg.Role = chat.ChatMessageRoleUser
242			}
243			items[i] = convertMessage(msg)
244		}
245	
246		ret = responses.ResponseNewParams{
247			Model: shared.ResponsesModel(opts.Model),
248			Input: responses.ResponseNewParamsInputUnion{
249				OfInputItemList: items,
250			},
251		}
252	
253		// Add tools if enabled
254		var tools []responses.ToolUnionParam
255	
256		// Add web search tool if enabled
257		if opts.Search {
258			webSearchTool := responses.ToolParamOfWebSearchPreview("web_search_preview")
259	
260			// Add user location if provided
261			if opts.SearchLocation != "" {
262				webSearchTool.OfWebSearchPreview.UserLocation = responses.WebSearchToolUserLocationParam{
263					Type:     "approximate",
264					Timezone: openai.String(opts.SearchLocation),
265				}
266			}
267	
268			tools = append(tools, webSearchTool)
269		}
270	
271		// Add image generation tool if needed
272		tools = o.addImageGenerationTool(opts, tools)
273	
274		if len(tools) > 0 {
275			ret.Tools = tools
276		}
277	
278		if eff, ok := parseReasoningEffort(opts.Thinking); ok {
279			ret.Reasoning = shared.ReasoningParam{Effort: eff}
280		}
281	
282		if !opts.Raw {
283			ret.Temperature = openai.Float(opts.Temperature)
284			if opts.TopP != 0 {
285				ret.TopP = openai.Float(opts.TopP)
286			}
287			if opts.MaxTokens != 0 {
288				ret.MaxOutputTokens = openai.Int(int64(opts.MaxTokens))
289			}
290	
291			// Add parameters not officially supported by Responses API as extra fields
292			extraFields := make(map[string]any)
293			if opts.PresencePenalty != 0 {
294				extraFields["presence_penalty"] = opts.PresencePenalty
295			}
296			if opts.FrequencyPenalty != 0 {
297				extraFields["frequency_penalty"] = opts.FrequencyPenalty
298			}
299			if opts.Seed != 0 {
300				extraFields["seed"] = opts.Seed
301			}
302			if len(extraFields) > 0 {
303				ret.SetExtraFields(extraFields)
304			}
305		}
306		return
307	}
308	
309	// BuildResponseParams exposes the shared Responses API request builder so
310	// auth-specialized vendors can reuse Fabric's OpenAI-compatible request shape.
311	func (o *Client) BuildResponseParams(
312		inputMsgs []*chat.ChatCompletionMessage, opts *domain.ChatOptions,
313	) responses.ResponseNewParams {
314		return o.buildResponseParams(inputMsgs, opts)
315	}
316	
317	func convertMessage(msg chat.ChatCompletionMessage) responses.ResponseInputItemUnionParam {
318		result := convertMessageCommon(msg)
319		role := responses.EasyInputMessageRole(result.Role)
320	
321		if result.HasMultiContent {
322			var parts []responses.ResponseInputContentUnionParam
323			for _, p := range result.MultiContent {
324				switch p.Type {
325				case chat.ChatMessagePartTypeText:
326					parts = append(parts, responses.ResponseInputContentParamOfInputText(p.Text))
327				case chat.ChatMessagePartTypeImageURL:
328					part := responses.ResponseInputContentParamOfInputImage(responses.ResponseInputImageDetailAuto)
329					if part.OfInputImage != nil {
330						part.OfInputImage.ImageURL = openai.String(p.ImageURL.URL)
331					}
332					parts = append(parts, part)
333				}
334			}
335			contentList := responses.ResponseInputMessageContentListParam(parts)
336			return responses.ResponseInputItemParamOfMessage(contentList, role)
337		}
338		return responses.ResponseInputItemParamOfMessage(result.Content, role)
339	}
340	
341	func (o *Client) extractText(resp *responses.Response) (ret string) {
342		var textParts []string
343		var citations []string
344		citationMap := make(map[string]bool) // To avoid duplicate citations
345	
346		for _, item := range resp.Output {
347			if item.Type == "message" {
348				for _, c := range item.Content {
349					if c.Type == "output_text" {
350						outputText := c.AsOutputText()
351						textParts = append(textParts, outputText.Text)
352	
353						// Extract citations from annotations
354						for _, annotation := range outputText.Annotations {
355							if annotation.Type == "url_citation" {
356								urlCitation := annotation.AsURLCitation()
357								citationKey := urlCitation.URL + "|" + urlCitation.Title
358								if !citationMap[citationKey] {
359									citationMap[citationKey] = true
360									citationText := fmt.Sprintf("- [%s](%s)", urlCitation.Title, urlCitation.URL)
361									citations = append(citations, citationText)
362								}
363							}
364						}
365					}
366				}
367				break
368			}
369		}
370	
371		ret = strings.Join(textParts, "")
372	
373		// Append citations if any were found
374		if len(citations) > 0 {
375			ret += "\n\n## Sources\n\n" + strings.Join(citations, "\n")
376		}
377	
378		return
379	}
380	
381	// ExtractText exposes the shared Responses API text extraction logic so other
382	// vendors can reuse Fabric's response formatting and citation handling.
383	func (o *Client) ExtractText(resp *responses.Response) string {
384		return o.extractText(resp)
385	}
