23		wrapped http.RoundTripper
24	}
25	
26	func (c *Client) ensureAccessToken(ctx context.Context, forceRefresh bool) (string, string, error) {
27		c.tokenMu.Lock()
28		defer c.tokenMu.Unlock()
29	
30		accessToken := strings.TrimSpace(c.AccessToken.Value)
31		accountID := strings.TrimSpace(c.AccountID.Value)
32	
33		if !forceRefresh && accessToken != "" && !tokenNeedsRefresh(accessToken, time.Now()) {
34			if accountID == "" {
35				parsedAccountID, err := extractAccountIDFromJWT(accessToken)
36				if err == nil && parsedAccountID != "" {
37					accountID = parsedAccountID
38					c.setSettingValue(c.AccountID, accountID)
39				}
40			}
41			if accountID != "" {
42				return accessToken, accountID, nil
43			}
44		}
45	
46		refreshed, err := c.refreshAccessToken(ctx)
47		if err != nil {
48			return "", "", err
49		}
50	
51		refreshedAccountID, err := c.extractAccountID(refreshed.IDToken, refreshed.AccessToken)
52		if err != nil {
53			return "", "", err
54		}
55		if accountID != "" && refreshedAccountID != "" && !strings.EqualFold(accountID, refreshedAccountID) {
56			return "", "", errors.New(i18n.T("codex_login_account_changed"))
57		}
58	
59		c.setSettingValue(c.AccessToken, refreshed.AccessToken)
60		if strings.TrimSpace(refreshed.RefreshToken) != "" {
61			c.setSettingValue(c.RefreshToken, refreshed.RefreshToken)
62		}
63		c.setSettingValue(c.AccountID, refreshedAccountID)
64		debuglog.Debug(debuglog.Detailed, "Codex access token refreshed for account=%s\n", refreshedAccountID)
65	
66		return c.AccessToken.Value, c.AccountID.Value, nil
67	}
68	
69	func (c *Client) refreshAccessToken(ctx context.Context) (oauthTokens, error) {
70		payload := refreshRequest{
71			ClientID:     oauthClientID,
72			GrantType:    "refresh_token",
73			RefreshToken: strings.TrimSpace(c.RefreshToken.Value),
74		}
75	
76		body, err := json.Marshal(payload)
77		if err != nil {
78			return oauthTokens{}, err
79		}
80	
81		tokenURL := strings.TrimRight(c.AuthBaseURL.Value, "/") + "/oauth/token"
82		req, err := http.NewRequestWithContext(ctx, http.MethodPost, tokenURL, strings.NewReader(string(body)))
83		if err != nil {
84			return oauthTokens{}, err
85		}
86		req.Header.Set("Content-Type", "application/json")
87	
88		resp, err := c.authHTTPClient.Do(req)
89		if err != nil {
90			return oauthTokens{}, fmt.Errorf(i18n.T("codex_refresh_login_failed"), err)
91		}
92		defer resp.Body.Close()
93	
94		responseBody, err := io.ReadAll(resp.Body)
95		if err != nil {
96			return oauthTokens{}, err
97		}
98		if resp.StatusCode != http.StatusOK {
99			return oauthTokens{}, c.refreshErrorFromResponse(resp.StatusCode, responseBody)
100		}
101	
102		var refreshed refreshResponse
103		if err := json.Unmarshal(responseBody, &refreshed); err != nil {
104			return oauthTokens{}, fmt.Errorf(i18n.T("codex_decode_refresh_response_failed"), err)
105		}
106		if strings.TrimSpace(refreshed.AccessToken) == "" {
107			return oauthTokens{}, errors.New(i18n.T("codex_token_refresh_missing_access_token"))
108		}
109	
110		return oauthTokens{
111			IDToken:      strings.TrimSpace(refreshed.IDToken),
112			AccessToken:  strings.TrimSpace(refreshed.AccessToken),
113			RefreshToken: strings.TrimSpace(refreshed.RefreshToken),
114		}, nil
115	}
116	
117	func (c *Client) extractAccountID(idToken string, accessToken string) (string, error) {
118		if accountID, err := extractAccountIDFromJWT(idToken); err == nil && accountID != "" {
119			return accountID, nil
120		}
121		if accountID, err := extractAccountIDFromJWT(accessToken); err == nil && accountID != "" {
122			return accountID, nil
123		}
124		return "", errors.New(i18n.T("codex_login_missing_account_claim"))
125	}
126	
127	func (c *Client) setSettingValue(setting *plugins.Setting, value string) {
128		setting.Value = value
129		if setting.EnvVariable != "" {
130			_ = os.Setenv(setting.EnvVariable, value)
131		}
132	}
133	
134	// RoundTrip adds Codex authentication headers and retries once after a 401.
135	func (t *authTransport) RoundTrip(req *http.Request) (*http.Response, error) {
136		return t.roundTrip(req, false)
137	}
138	
139	func (t *authTransport) roundTrip(req *http.Request, retried bool) (*http.Response, error) {
140		token, accountID, err := t.client.ensureAccessToken(req.Context(), false)
141		if err != nil {
142			return nil, err
143		}
144	
145		clone, err := cloneRequest(req)
146		if err != nil {
147			return nil, err
148		}
149		clone.Header.Set(http.CanonicalHeaderKey("originator"), defaultOriginator)
150		clone.Header.Set("User-Agent", defaultUserAgent)
151		clone.Header.Set("Authorization", "Bearer "+token)
152		clone.Header.Set("ChatGPT-Account-ID", accountID)
153	
154		resp, err := t.roundTripper().RoundTrip(clone)
155		if err != nil {
156			return nil, err
157		}
158		if resp.StatusCode != http.StatusUnauthorized || retried {
159			return resp, nil
160		}
161	
162		drainAndClose(resp.Body)
163		debuglog.Debug(debuglog.Detailed, "Codex request returned 401; attempting token refresh and one retry\n")
164	
165		if _, _, err := t.client.ensureAccessToken(req.Context(), true); err != nil {
166			return nil, err
167		}
168	
169		return t.roundTrip(req, true)
170	}
171	
172	func (t *authTransport) roundTripper() http.RoundTripper {
173		if t.wrapped != nil {
174			return t.wrapped
175		}
176		return http.DefaultTransport
177	}
178	
179	func cloneRequest(req *http.Request) (*http.Request, error) {
180		clone := req.Clone(req.Context())
181		if req.Body == nil || req.Body == http.NoBody {
182			return clone, nil
183		}
184		// Codex retry logic assumes GetBody is available so the request can be replayed after refresh.
185		if req.GetBody == nil {
186			return nil, errReplayBodyUnavailable
187		}
188	
189		body, err := req.GetBody()
190		if err != nil {
191			return nil, err
192		}
193		clone.Body = body
194		return clone, nil
195	}
196	
197	func drainAndClose(body io.ReadCloser) {
198		if body == nil {
199			return
200		}
201		_, _ = io.Copy(io.Discard, io.LimitReader(body, defaultRoundTripLimit))
202		_ = body.Close()
203	}
204

